from pyspark.sql import functions as F, Window as W

def money(col):
    return F.col(col).cast("decimal(12,2)")

def keep_latest(df, keys):
    w = W.partitionBy(*keys).orderBy(F.col("_ingested_at").desc())
    return df.withColumn("_rn", F.row_number().over(w)).filter("_rn = 1").drop("_rn")

def parse_ts(col):
    """ISO timestamps normally; day-first after the July 2024 system change."""
    c = F.trim(F.col(col))
    return (F.when(c.rlike(r"^\d{4}-"), F.to_timestamp(c, "yyyy-MM-dd HH:mm:ss"))
             .otherwise(F.to_timestamp(c, "dd/MM/yyyy HH:mm")))

# Every spelling seen in the source -> one English name (keys in lower case)
CITY_MAP = {
    "الرياض": "Riyadh", "riyadh": "Riyadh", "riyadh city": "Riyadh",
    "جدة": "Jeddah", "jeddah": "Jeddah", "jiddah": "Jeddah",
    "مكة المكرمة": "Makkah", "makkah": "Makkah", "mecca": "Makkah",
    "المدينة المنورة": "Madinah", "madinah": "Madinah", "medina": "Madinah",
    "الدمام": "Dammam", "dammam": "Dammam",
}
city_lookup = F.create_map([F.lit(x) for pair in CITY_MAP.items() for x in pair])

def standard_city(col):
    raw = F.trim(F.col(col))
    return F.coalesce(city_lookup[F.lower(raw)], F.initcap(raw))

import subprocess
import sys
from pathlib import Path

import pandas as pd
import pytest

SCRIPT = Path(__file__).parents[1] / "scripts" / "generate_saudi_retail.py"


@pytest.fixture(scope="session")
def landing(tmp_path_factory):
    out = tmp_path_factory.mktemp("generated")
    subprocess.run([sys.executable, str(SCRIPT)], cwd=out, check=True)
    return out / "landing"


def read_all(landing, name):
    files = sorted((landing / "sales").glob(f"*/{name}.csv"))
    return pd.concat(pd.read_csv(f, encoding="utf-8-sig") for f in files)


def test_36_months_with_three_files(landing):
    months = sorted((landing / "sales").iterdir())
    assert len(months) == 36
    for m in months:
        assert {f.name for f in m.iterdir()} == {"orders.csv", "order_items.csv", "payments.csv"}


def test_vat_is_15_percent(landing):
    items = read_all(landing, "order_items")
    net = items.unit_price_sar * items.quantity - items.discount_sar
    assert ((items.vat_sar - net * 0.15).abs() <= 0.01).all()


def test_payments_match_order_totals(landing):
    items = read_all(landing, "order_items").drop_duplicates()   # duplicates are exact copies
    items["gross"] = (items.unit_price_sar * items.quantity - items.discount_sar + items.vat_sar)
    totals = items.groupby("order_id", as_index=False).gross.sum()
    merged = read_all(landing, "payments").merge(totals, on="order_id")
    assert ((merged.amount_sar - merged.gross).abs() <= 0.05).all()
